/* =====================================================
   reviews.js : the review windows, like old computer windows. Needs css/reviews.css.
   From any page:  showReviews()      (it only ever shows once per visit)
   Two windows pop up, each "loads" for a moment, then the review (a tall still picture) can be scrolled inside it.
   Pictures: images/review-frame.png (the window, 706 x 472) and the reviews in REVIEWS below (700 wide, any height).
   ===================================================== */
(function () {
  const FRAME = 'images/review-frame.png';
  const REVIEWS = [                                        // one per window
    { img: 'images/review-1.png' },
    { img: 'images/review-2.png', corrupt: true }          // corrupt: when they scroll to the very end it goes black, the site panics, and the window becomes the error picture
  ];
  const ERROR_IMG = 'images/review-error.png', ERR_W = 360;   // the error picture and its width on screen (before shrinking to fit small screens)
  const CORRUPT_AFTER = 700;   // ms after reaching the end (so they see the bottom first)
  const DEAD_LINES = ['anomaly detected...', 'please, we assure you nothing is wrong, all is real, all is fine'];
  const DEAD_SPEED = 45, DEAD_GAP = 700, DEAD_HOLD = 2200;    // typing speed, pause between the two lines, how long both stay before the error picture
  const GLITCH = [1, 1, 0, 1, 0, 1, 1, 0, 1, 0];              // the flicker: 1 = glitchy, 0 = gone for a moment
  const LOAD_FOR = 2000;       // ms each window "loads" before the review shows
  const SECOND_AFTER = 1000;   // ms between the first window and the second
  const KEY = 'realStuf.reviews';
  const COOKIES_IMG = 'images/cookies.png', COOKIES_W = 560;   // the cookies notification (your picture) and its width on screen (it shrinks to fit small screens)
  const COOKIES_AFTER = 7000;                                 // ms after the corrupted review's black "anomaly detected" screen has gone, then the cookies notification appears (on whichever page they are on)
  const DREAD_STEP = 0.12;                                    // each time they try DECLINE or the X, the dark vignette around the screen gets this much darker (js/vignette.js; 1 = the darkest it can be)
  const CK_SHOWN = 'realStuf.cookies', CK_DUE = 'realStuf.cookiesAt';   // shown once per visit; the time it is due is written down, so clicking into another page does not lose it
  const CK_HIT = {                                            // the clickable spots on the picture (% of the picture: left, top, width, height)
    decline: [32.9, 73.8, 29.5, 20.0], accept: [66.6, 73.8, 29.3, 20.0], x: [92.8, 3.6, 4.9, 9.3]
  };
  const FW = 706, FH = 472;    // the frame picture's size
  let layer = null, shown = false, top = 1;
  const told = {};

  /* ---------- the windows stay until the sequence is over: where each one is up to is written down, and the next page puts them back ----------
     w0 / w1 (the normal review / the corrupted one): 'open' | 'dying' (the black "anomaly detected" screen) | 'err' (the error picture) | 'closed'.
     The sequence is over when both are closed (the error picture is closed with Ok or the X). */
  const ST = 'realStuf.rvState';
  let RV = null;
  try { RV = JSON.parse(sessionStorage.getItem(ST) || 'null'); } catch (e) {}
  const rvSave = function () { try { if (RV) sessionStorage.setItem(ST, JSON.stringify(Object.assign(RV, { told: told }))); } catch (e) {} };
  const rvSet = function (k, v) { if (!RV) return; RV[k] = v; if (RV.w0 === 'closed' && RV.w1 === 'closed') RV.on = false; rvSave(); };
  if (RV && RV.told) Object.assign(told, RV.told);
  const tell = function (what) { window.dispatchEvent(new CustomEvent('realstuf:review', { detail: what })); };   // js/assistant.js listens: Maya reacts

  function once() { try { if (sessionStorage.getItem(KEY)) return true; sessionStorage.setItem(KEY, '1'); } catch (e) {} return false; }

  const TOP_AT = .2;                                         // how far down the first window sits (share of the screen height; 0.1 = near the top, 0.3 = lower). The second one is always 56px lower than the first. The windows shrink a little if they would run off the bottom.

  // where each window goes on this screen: one left, one right, the second a little lower. On a narrow screen (under 900px) they overlap in the middle.
  function place(win, i) {
    const vw = innerWidth, vh = innerHeight;
    const wide = vw >= 900;                                  // room for both side by side? then they are shrunk to fit (so neither covers the other's scrollbar)
    const top = Math.max(90, vh * TOP_AT);
    const s = Math.min(1, wide ? vw * .96 / (2 * FW) : (vw - 16) / FW, (vh - top - 56 - 24) / FH), w = FW * s;
    const left = wide ? (i ? vw - w - vw * .02 : vw * .02) : Math.max(8, (vw - w) / 2) + (i ? 20 : 0);
    const y = top + (i ? 56 : 0);
    win.style.cssText += ';left:' + left + 'px;top:' + y + 'px;transform:scale(' + s + ')';
    win.dataset.s = s;
  }

  function build(cfg, i, restore) {
    const src = cfg.img;
    const win = document.createElement('div');
    win.className = 'rv-win';
    win.innerHTML =
      '<img class="rv-frame" alt="" src="' + FRAME + '">' +
      '<div class="rv-body"><div class="rv-dead"><p></p><p></p></div><div class="rv-load"><b>' + [0, 1, 2, 3, 4, 5, 6, 7].map(function (k) { const a = k * Math.PI / 4; return '<i style="left:' + (23 + 23 * Math.sin(a)) + 'px;top:' + (23 - 23 * Math.cos(a)) + 'px;animation-delay:' + (-0.8 + k * .1) + 's"></i>'; }).join('') + '</b>loading...</div>' +
        '<div class="rv-scroll"><div class="rv-page"><img alt="A customer review" src="' + src + '"><button class="rv-close" type="button">close review</button></div></div></div>' +
      '<div class="rv-bar"><button class="rv-up" type="button" aria-label="Scroll up"></button><div class="rv-track"><div class="rv-thumb"></div></div><button class="rv-dn" type="button" aria-label="Scroll down"></button></div>';
    win.dataset.i = i;
    place(win, i);
    if (restore) win.style.animation = 'none';                  // put back on the next page: no fade-in, no loading spinner, no sound
    layer.appendChild(win);
    if (!restore) window.sfx && sfx('thud');
    wire(win, cfg);
    if (restore) {
      win.classList.add('ready'); sync(win);
      const sc = win.querySelector('.rv-scroll'), pic = win.querySelector('.rv-page img'), at = RV && RV['s' + i] || 0;
      const back = function () { sync(win); sc.scrollTop = at; sync(win); };
      if (pic.complete) back(); else pic.addEventListener('load', back, { once: true });
    } else setTimeout(function () { win.classList.add('ready'); sync(win); }, LOAD_FOR);
    return win;
  }

  function wire(win, cfg) {
    const sc = win.querySelector('.rv-scroll'), thumb = win.querySelector('.rv-thumb'), track = win.querySelector('.rv-track');
    win.addEventListener('pointerdown', function () { win.style.zIndex = ++top; });                 // click a window to bring it to the front
    const idx = +win.dataset.i; let saveT = 0;
    sc.addEventListener('scroll', function () {
      sync(win);
      clearTimeout(saveT); saveT = setTimeout(function () { if (RV && RV['w' + idx] === 'open') { RV['s' + idx] = sc.scrollTop; rvSave(); } }, 120);   // remember how far they have read
      if (!cfg.corrupt && win.classList.contains('ready') && sc.scrollTop > 60 && !told.read) { told.read = 1; rvSave(); tell('read'); }      // they are reading the normal review: Maya comments (js/assistant.js)
      if (cfg.corrupt && !win.dataset.dead && win.classList.contains('ready') && sc.scrollTop >= sc.scrollHeight - sc.clientHeight - 3) {   // they reached the very end
        win.dataset.dead = '1'; if (!told.corrupt) { told.corrupt = 1; rvSave(); tell('corrupt'); }                    // ...and when the bad one reaches its end
        setTimeout(function () { corrupt(win); }, CORRUPT_AFTER);
      }
    });
    win.querySelector('.rv-close').addEventListener('click', function () {
      window.sfx && sfx('click');
      win.classList.add('out'); rvSet('w' + idx, 'closed');
      setTimeout(function () { win.remove(); if (layer && !layer.children.length) { layer.remove(); layer = null; } }, 260);
    });
    // the arrows scroll while held
    [['.rv-up', -1], ['.rv-dn', 1]].forEach(function (a) {
      const b = win.querySelector(a[0]); let t;
      b.addEventListener('pointerdown', function (e) { e.preventDefault(); const go = function () { sc.scrollTop += a[1] * 48; }; go(); t = setInterval(go, 70); });
      ['pointerup', 'pointerleave', 'pointercancel'].forEach(function (ev) { b.addEventListener(ev, function () { clearInterval(t); }); });
    });
    // the handle drags (the window can be scaled, so movement is divided by the scale)
    thumb.addEventListener('pointerdown', function (e) {
      e.preventDefault(); thumb.setPointerCapture(e.pointerId);
      const s = +win.dataset.s || 1, y0 = e.clientY, top0 = sc.scrollTop;
      const room = track.clientHeight - thumb.offsetHeight, max = sc.scrollHeight - sc.clientHeight;
      const move = function (m) { sc.scrollTop = top0 + ((m.clientY - y0) / s) / (room || 1) * max; };
      const up = function () { thumb.removeEventListener('pointermove', move); thumb.removeEventListener('pointerup', up); };
      thumb.addEventListener('pointermove', move); thumb.addEventListener('pointerup', up);
    });
    // a click on the empty track pages up or down
    track.addEventListener('pointerdown', function (e) {
      if (e.target !== track) return;
      const r = thumb.getBoundingClientRect();
      sc.scrollTop += (e.clientY < r.top ? -1 : 1) * sc.clientHeight * .9;
    });
    win.querySelector('.rv-page img').addEventListener('load', function () { sync(win); });
    addEventListener('resize', function () { if (win.isConnected) { place(win, [].indexOf.call(layer.children, win)); sync(win); } });
  }

  function sync(win) {                                       // the handle's size and place follow the scrolling
    const sc = win.querySelector('.rv-scroll'), thumb = win.querySelector('.rv-thumb'), track = win.querySelector('.rv-track');
    const max = sc.scrollHeight - sc.clientHeight, h = track.clientHeight;
    if (max <= 0 || !h) { thumb.style.display = 'none'; return; }
    thumb.style.display = '';
    const th = Math.max(30, h * sc.clientHeight / sc.scrollHeight);
    thumb.style.height = th + 'px';
    thumb.style.top = (sc.scrollTop / max) * (h - th) + 'px';
  }

  /* ---------- the corruption: glitch, black, the site panics, then the window becomes the error picture ---------- */
  function flicker(el, move, done) {
    const rnd = function (a, b) { return a + Math.random() * (b - a); };
    let i = 0;
    (function tick() {
      if (i >= GLITCH.length) { el.style.visibility = el.style.filter = el.style.clipPath = ''; if (move) el.style.transform = ''; done(); return; }
      if (GLITCH[i]) {
        window.sfx && sfx('static');
        el.style.visibility = 'visible';
        if (move) el.style.transform = 'translate(' + rnd(-30, 30) + 'px,' + rnd(-4, 4) + 'px) skewX(' + rnd(-8, 8) + 'deg)';
        el.style.clipPath = 'inset(' + rnd(0, 55) + '% 0 ' + rnd(0, 35) + '% 0)';
        el.style.filter = Math.random() < .5 ? 'invert(1) hue-rotate(' + rnd(0, 360) + 'deg)' : 'none';
      } else el.style.visibility = 'hidden';
      i++; setTimeout(tick, rnd(60, 130));
    })();
  }

  function typeInto(node, text, done) {
    let n = 0;
    (function next() {
      node.textContent = text.slice(0, ++n);
      if (window.sfx && text[n - 1] !== ' ') sfx('key');
      if (n >= text.length) { if (done) done(); return; }
      setTimeout(next, (text[n - 1] === '.' ? DEAD_SPEED * 2.5 : DEAD_SPEED) + Math.random() * DEAD_SPEED * .8 - DEAD_SPEED * .4);
    })();
  }

  function corrupt(win) {
    if (!win.isConnected) return;
    win.classList.add('dying'); rvSet('w1', 'dying');             // scrolling and the close button are locked
    flicker(win.querySelector('.rv-body'), true, function () {
      win.classList.add('dead');                                  // black
      const p = win.querySelectorAll('.rv-dead p');
      setTimeout(function () {
        typeInto(p[0], DEAD_LINES[0], function () {
          setTimeout(function () { typeInto(p[1], DEAD_LINES[1], function () { setTimeout(function () { swapForError(win); }, DEAD_HOLD); }); }, DEAD_GAP);
        });
      }, 500);
    });
  }

  function swapForError(win) {
    if (!win.isConnected) return;
    const r = win.getBoundingClientRect(), s = +win.dataset.s || 1;
    flicker(win, false, function () {
      win.remove();
      scheduleCookies(COOKIES_AFTER);                       // the black screen is gone: the cookies notification is due in a few seconds (js below)
      RV && (RV.err = { x: (r.left + r.width / 2) / innerWidth, y: (r.top + r.height / 2) / innerHeight, s: s });
      showError(r.left + r.width / 2, r.top + r.height / 2, s, false);
    });
  }
  function showError(cx, cy, s, restore) {                  // the error picture: also put back on the next page if it has not been closed yet
    if (!layer) { layer = document.createElement('div'); layer.className = 'rv-layer'; document.body.appendChild(layer); }
    const err = document.createElement('div');
    err.className = 'rv-err';
    err.style.cssText = 'left:' + cx + 'px;top:' + cy + 'px;width:' + ERR_W * s + 'px;z-index:' + (++top) + (restore ? ';animation:none' : '');
    err.innerHTML = '<img alt="Critical error" src="' + ERROR_IMG + '"><button class="rv-errx" type="button" aria-label="Close"></button><button class="rv-ok" type="button" aria-label="Ok"></button>';
    layer.appendChild(err);
    rvSet('w1', 'err');
    if (!restore) window.sfx && sfx('warn', 3);
    const gone = function () {
      window.sfx && sfx('click'); err.classList.add('out'); rvSet('w1', 'closed');
      setTimeout(function () { err.remove(); if (layer && !layer.children.length) { layer.remove(); layer = null; } }, 260);
    };
    err.querySelector('.rv-ok').addEventListener('click', gone);
    err.querySelector('.rv-errx').addEventListener('click', gone);
  }

  /* ---------- the cookies notification: your picture, a few seconds after the corrupted review's black screen. Hover DECLINE: a red vignette fills the screen edges. ---------- */
  let ckTimer = 0, ckLayer = null, ckVig = null;
  function scheduleCookies(ms) {
    try { if (sessionStorage.getItem(CK_SHOWN)) return; sessionStorage.setItem(CK_DUE, String(Date.now() + ms)); } catch (e) {}
    clearTimeout(ckTimer); ckTimer = setTimeout(function () { showCookies(); }, ms);
  }
  function showCookies(force) {
    if (ckLayer) return;
    try { if (!force && sessionStorage.getItem(CK_SHOWN)) return; sessionStorage.setItem(CK_SHOWN, '1'); sessionStorage.removeItem(CK_DUE); } catch (e) {}
    if (!document.querySelector('link[href*="reviews.css"]')) { const l = document.createElement('link'); l.rel = 'stylesheet'; l.href = 'css/reviews.css'; document.head.appendChild(l); }
    ckVig = document.createElement('div'); ckVig.className = 'ck-vig'; ckVig.setAttribute('aria-hidden', 'true'); document.body.appendChild(ckVig);
    ckLayer = document.createElement('div'); ckLayer.className = 'ck-layer';
    const win = document.createElement('div'); win.className = 'ck-win'; win.setAttribute('role', 'dialog'); win.setAttribute('aria-label', 'Cookies Settings');
    win.style.width = 'min(' + COOKIES_W + 'px, 92vw)';
    win.innerHTML = '<img alt="Cookies Settings" src="' + COOKIES_IMG + '">';
    const spot = function (name, label) {
      const b = document.createElement('button'), h = CK_HIT[name];
      b.type = 'button'; b.className = 'ck-' + name; b.setAttribute('aria-label', label);
      b.style.cssText = 'left:' + h[0] + '%;top:' + h[1] + '%;width:' + h[2] + '%;height:' + h[3] + '%';
      win.appendChild(b); return b;
    };
    const dec = spot('decline', 'Decline'), acc = spot('accept', 'Accept'), x = spot('x', 'Close');
    ckLayer.appendChild(win); document.body.appendChild(ckLayer);
    ['wheel', 'touchmove'].forEach(function (ev) { ckLayer.addEventListener(ev, function (e) { e.preventDefault(); }, { passive: false }); });      // the page behind cannot be scrolled either
    window.sfx && (sfx('thud'), sfx('warn', 1));
    const vig = function (on) { ckVig.classList.toggle('on', on); };
    dec.addEventListener('pointerenter', function () { vig(true); window.sfx && sfx('warn', 2); });       // hover DECLINE: the red vignette
    dec.addEventListener('pointerleave', function () { vig(false); });                                     // hover away: it goes
    dec.addEventListener('blur', function () { vig(false); });
    dec.addEventListener('focus', function () { vig(true); });
    const gone = function () {
      window.sfx && sfx('click'); vig(false); win.classList.add('out');
      setTimeout(function () { ckLayer && ckLayer.remove(); ckVig && ckVig.remove(); ckLayer = ckVig = null; }, 300);
    };
    acc.addEventListener('click', gone);                                                                  // ACCEPT closes it
    let refused = 0;
    const refuse = function () {                                                                           // DECLINE and the X do NOT close it: it shakes, the red vignette flashes then fades, the dark vignette gets darker, and Maya notices
      refused++;
      window.sfx && (sfx('thud'), sfx('warn', 3));
      win.classList.remove('shake'); void win.offsetWidth; win.classList.add('shake');
      ckVig.classList.remove('on'); ckVig.classList.remove('flash'); void ckVig.offsetWidth; ckVig.classList.add('flash');
      window.dispatchEvent(new CustomEvent('realstuf:dread', { detail: DREAD_STEP }));                    // js/vignette.js: the dark vignette closes in a little more
      window.dispatchEvent(new CustomEvent('realstuf:cookies', { detail: refused }));                     // js/assistant.js: Maya comments
    };
    ckVig.addEventListener('animationend', function () { ckVig.classList.remove('flash'); });
    dec.addEventListener('click', refuse); x.addEventListener('click', refuse);
  }
  window.showCookies = showCookies;                          // testing: showCookies(true) in the console
  (function () {                                             // a page that loads while the notification is due (they clicked into another page): it appears here instead
    let at = 0; try { at = +sessionStorage.getItem(CK_DUE) || 0; if (sessionStorage.getItem(CK_SHOWN)) at = 0; } catch (e) {}
    if (at) { clearTimeout(ckTimer); ckTimer = setTimeout(function () { showCookies(); }, Math.max(0, at - Date.now())); }
  })();

  window.showReviews = function (force) {                    // force = show them even if they were shown already this visit (testing)
    if (shown || (!force && once())) { console.info('reviews: not shown, they already appeared in this tab. Open a new tab, or add ?reviews=1 to the address.'); return; }
    console.info('reviews: showing the review windows');
    shown = true; RV = { on: true, w0: 'open', w1: 'open', s0: 0, s1: 0 }; rvSave();
    if (!document.querySelector('link[href*="reviews.css"]')) {   // the page forgot the stylesheet link: add it, so the windows are never unstyled
      const l = document.createElement('link'); l.rel = 'stylesheet'; l.href = 'css/reviews.css'; document.head.appendChild(l);
      console.warn('reviews: your page has no <link> to css/reviews.css, so it was added automatically. Add this line to the <head>: <link rel="stylesheet" href="css/reviews.css">');
    }
    layer = document.createElement('div');
    layer.className = 'rv-layer';
    document.body.appendChild(layer);
    ['css/reviews.css', FRAME, REVIEWS[0].img, REVIEWS[1].img].forEach(function (u) { fetch(u, { method: 'HEAD' }).then(function (r) { if (!r.ok) console.warn('reviews: cannot find ' + u + ' (' + r.status + ')'); }).catch(function () {}); });
    build(REVIEWS[0], 0);
    setTimeout(function () { if (layer) build(REVIEWS[1] || REVIEWS[0], 1); }, SECOND_AFTER);
  };
  // a page that loads in the middle of the sequence puts the windows back as they were (the same place, the same spot in the review), until the sequence is over
  (function restore() {
    if (!RV || !RV.on || shown) return;
    shown = true;
    if (!document.querySelector('link[href*="reviews.css"]')) { const l = document.createElement('link'); l.rel = 'stylesheet'; l.href = 'css/reviews.css'; document.head.appendChild(l); }
    layer = document.createElement('div'); layer.className = 'rv-layer'; document.body.appendChild(layer);
    if (RV.w0 === 'open') build(REVIEWS[0], 0, true);
    if (RV.w1 === 'open') build(REVIEWS[1] || REVIEWS[0], 1, true);
    if (RV.w1 === 'dying') { const w = build(REVIEWS[1] || REVIEWS[0], 1, true); w.dataset.dead = '1'; setTimeout(function () { corrupt(w); }, 300); }   // it was in the middle of dying: it starts again
    if (RV.w1 === 'err' && RV.err) showError(RV.err.x * innerWidth, RV.err.y * innerHeight, RV.err.s, true);
    if (!layer.children.length) { layer.remove(); layer = null; }
  })();
  // testing shortcut: open home.html?reviews=1 and the windows pop up a moment after the page loads, whatever the story stage
  if (/[?&]reviews=1/.test(location.search)) setTimeout(function () { showReviews(true); }, 1200);
  if (/[?&]cookies=1/.test(location.search)) setTimeout(function () { showCookies(true); }, 1200);          // testing shortcut: the cookies notification on its own
})();
